args.command:
/bin/bash -lc "cat <<'EOF' > app/lib/analytics.ts
import \"server-only\";

type PageViewEvent = {
  path: string;
  userAgent: string | null;
  referrer: string | null;
  timestamp: string;
};

export async function logPageView(event: PageViewEvent): Promise<void> {
  const endpoint = process.env.ANALYTICS_ENDPOINT;

  if ("'!endpoint) {
    console.log("analytics.page_view", event);
    return;
  }

  await fetch(endpoint, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(event),
    keepalive: true,
  });
}
EOF'

